// Normalize incoming message & extract user identity securely
const currentInput = $input.first()?.json || {};

// Check if triggered from WhatsApp
const isWhatsApp = Boolean(
  currentInput.body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0] ||
  currentInput.entry?.[0]?.changes?.[0]?.value?.messages?.[0] ||
  currentInput.object === 'whatsapp_business_account' ||
  currentInput.body?.object === 'whatsapp_business_account'
);

let channel = isWhatsApp ? 'whatsapp' : 'website';
let role = 'customer';
let rawMessage = '';
let transcribedText = '';
let safeUserEmail = '';
let safeUserPhone = '';
let safeUserId = '';
let userName = '';
let whatsappPhoneNumberId = '1464619796732128';
let whatsappMessageId = '';
let isLoggedIn = false;
let history = [];
let formattedHistory = '';
let storeContext = null;

if (isWhatsApp) {
  // Extract WhatsApp Cloud API Message Structure
  const changeValue = currentInput.body?.entry?.[0]?.changes?.[0]?.value || currentInput.entry?.[0]?.changes?.[0]?.value || currentInput;
  const waContact = changeValue.contacts?.[0] || {};
  const waMsg = changeValue.messages?.[0] || {};

  whatsappPhoneNumberId = String(changeValue.metadata?.phone_number_id || '1464619796732128');
  whatsappMessageId = waMsg.id || '';

  const rawSenderPhone = waMsg.from || waContact.wa_id || '';
  safeUserPhone = rawSenderPhone.replace(/[^0-9+]/g, '').slice(0, 20);

  const rawSenderName = waContact.profile?.name || 'WhatsApp Customer';
  userName = rawSenderName.replace(/[<>"';]/g, '').slice(0, 80);

  if (waMsg.type === 'text') {
    rawMessage = waMsg.text?.body || '';
  } else if (waMsg.type === 'interactive') {
    rawMessage = waMsg.interactive?.button_reply?.title || waMsg.interactive?.list_reply?.title || '';
  } else if (waMsg.type === 'button') {
    rawMessage = waMsg.button?.text || '';
  } else if (waMsg.type === 'audio') {
    rawMessage = '[Customer sent a voice note]';
  } else {
    rawMessage = waMsg.text?.body || '';
  }

  // Admin WhatsApp Verification (Configure store owner WhatsApp number for admin mode)
  const adminPhones = ['923001234567'];
  if (adminPhones.includes(safeUserPhone)) {
    role = 'admin';
  }
} else {
  // Website Chat Processing
  let webhookItem = {};
  try {
    webhookItem = $('Website Chat Webhook').first()?.json || $('Website Chat Webhook').item?.json || {};
  } catch (_) {
    webhookItem = currentInput;
  }
  const body = webhookItem.body || webhookItem;
  const headers = webhookItem.headers || {};

  if (currentInput && currentInput.text && typeof currentInput.text === 'string') {
    transcribedText = currentInput.text.trim();
  }
  if (!transcribedText) {
    try {
      const stt = $('Transcribe Voice (OpenRouter STT)').first()?.json;
      if (stt && stt.text) {
        transcribedText = String(stt.text).trim();
      }
    } catch (_) {}
  }

  rawMessage = (transcribedText || body.message || '').trim();

  // Role verification & Privilege Escalation Protection
  const adminSecretHeader = headers['x-admin-secret'] || headers['x-admin-key'] || '';
  const adminSecretBody = body.adminSecret || body.adminKey || '';
  const hasServerStoreContext = Boolean(body.storeContext && typeof body.storeContext === 'object' && body.storeContext.orders);
  const isValidAdminSecret = (adminSecretHeader === 'icare_admin_secret_2026_xyz' || adminSecretBody === 'icare_admin_secret_2026_xyz');
  const requestedRole = (body.role || 'customer').toLowerCase();
  role = (requestedRole === 'admin' && (isValidAdminSecret || hasServerStoreContext)) ? 'admin' : 'customer';

  const rawEmail = (body.userEmail || '').trim().toLowerCase();
  safeUserEmail = rawEmail.replace(/[^a-zA-Z0-9@._+-]/g, '').slice(0, 100);

  const rawPhone = (body.userPhone || '').trim();
  safeUserPhone = rawPhone.replace(/[^0-9+]/g, '').slice(0, 20);

  const rawUserId = String(body.userId || '').trim();
  safeUserId = rawUserId.replace(/[^0-9]/g, '').slice(0, 12);

  isLoggedIn = Boolean(body.isLoggedIn && (safeUserEmail || safeUserId));

  const rawUserName = (body.userName || body.senderName || (role === 'admin' ? 'Store Admin' : (isLoggedIn ? 'Registered Customer' : 'Guest Customer'))).trim();
  userName = rawUserName.replace(/[<>"';]/g, '').slice(0, 80);

  if (Array.isArray(body.history) && body.history.length > 0) {
    history = body.history.slice(-8);
    formattedHistory = history.slice(-6).map(h => {
      const roleLabel = (h.role === 'user' || h.role === 'human') ? 'User' : 'Assistant';
      const content = (typeof h.content === 'string' ? h.content : JSON.stringify(h.content || '')).trim();
      return roleLabel + ': ' + content;
    }).filter(Boolean).join('\n');
  }

  if (role === 'admin') {
    storeContext = body.storeContext || null;
  }
}

// Sanitization & Order Extraction
const messageText = rawMessage.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, '').slice(0, 2000);
const orderMatch = messageText.match(/(?:order|id|#|no|track|parcel)\s*([0-9]{4,16})/i) || messageText.match(/\b([0-9]{4,16})\b/);
const safeOrderIdQuery = orderMatch ? orderMatch[1].replace(/[^0-9]/g, '').slice(0, 16) : '';

return [{
  json: {
    channel: channel,
    businessId: 'icare',
    role: role,
    isLoggedIn: isLoggedIn,
    userId: safeUserId,
    userEmail: safeUserEmail,
    userName: userName,
    userPhone: safeUserPhone,
    orderIdQuery: safeOrderIdQuery,
    message: messageText || (role === 'admin' ? 'Store status update' : 'Customer inquiry'),
    userText: transcribedText || messageText || '',
    history: history,
    formattedHistory: formattedHistory,
    storeContext: storeContext,
    whatsappPhoneNumberId: whatsappPhoneNumberId,
    whatsappMessageId: whatsappMessageId
  }
}];

